package org.sleepwell.app;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
@org.junit.runner.RunWith(org.junit.runners.JUnit4.class)
public class WakeCheckEngineTest {
 static final class Clock implements WakeCheckState.Clock {long wall=2000000000000L,elapsed=500000,boot=3;public long wall(){return wall;}public long elapsed(){return elapsed;}public long boot(){return boot;}void advance(long ms){wall+=ms;elapsed+=ms;}}
 static final class Store implements WakeCheckEngine.Store {WakeCheckState state;boolean fail;public WakeCheckState load(){return state;}public void save(WakeCheckState s){if(fail)throw new IllegalStateException();state=s;}}
 static final class Port implements WakeCheckEngine.Port {final Store store;boolean owner=true,failShow,failSchedule,failRing;String access="";int shown,rings,scheduled;long delay;WakeCheckEngine.Stage stage;final List<String> cancelled=new ArrayList<>();Port(Store s){store=s;}public boolean owner(WakeCheckState s){return owner;}public String access(){return access;}public void schedule(WakeCheckState s,WakeCheckEngine.Stage stage,long delay){if(failSchedule)throw new IllegalStateException();scheduled++;this.stage=stage;this.delay=delay;}public void cancel(WakeCheckState s){cancelled.add(s.nonce);}public void show(WakeCheckState s){if(failShow)throw new IllegalStateException();shown++;}public void ring(WakeCheckState s){assertEquals(WakeCheckState.Phase.CLAIMED,store.state.phase);rings++;if(failRing)throw new IllegalStateException();}}
 final Clock c=new Clock();final Store s=new Store();final Port p=new Port(s);final WakeCheckEngine e=new WakeCheckEngine(s,p,c);final String nonce=UUID.randomUUID().toString();
 WakeCheckState waiting(){return WakeCheckState.waiting(nonce,"occurrence","{}","Workdays",1,600000,false,c);}
 void prompt(){e.arm(waiting());c.advance(600000);e.receive(nonce,WakeCheckEngine.Stage.PROMPT);}
 @Test public void delayMeansSilentPromptThenSeparateTwoMinuteWindow(){e.arm(waiting());assertEquals(600000,p.delay);assertEquals(0,p.shown);assertEquals(0,p.rings);c.advance(600000);e.receive(nonce,WakeCheckEngine.Stage.PROMPT);assertEquals(1,p.shown);assertEquals(WakeCheckEngine.Stage.EXPIRE,p.stage);assertEquals(120000,p.delay);assertEquals(120000,s.state.remaining(c));assertEquals(0,p.rings);}
 @Test public void duplicatePromptAndRecreationNeverExtendDeadline(){prompt();long wall=s.state.deadlineWall,elapsed=s.state.deadlineElapsed;c.advance(17000);e.receive(nonce,WakeCheckEngine.Stage.PROMPT);new WakeCheckEngine(s,p,c).reconcile();assertEquals(wall,s.state.deadlineWall);assertEquals(elapsed,s.state.deadlineElapsed);assertEquals(103000,p.delay);assertEquals(1,p.shown);}
 @Test public void onlyOwnedNonceCanConfirmAndConfirmationIsDurable(){prompt();assertFalse(e.confirm(UUID.randomUUID().toString()));assertTrue(e.confirm(nonce));assertFalse(e.confirm(nonce));c.advance(120000);e.receive(nonce,WakeCheckEngine.Stage.EXPIRE);assertEquals(0,p.rings);assertEquals(WakeCheckState.Phase.CONFIRMED,s.state.phase);assertTrue(p.cancelled.stream().allMatch(nonce::equals));}
 @Test public void expiryClaimsBeforeEffectAndCannotRingTwice(){prompt();c.advance(120000);assertFalse(e.confirm(nonce));e.receive(nonce,WakeCheckEngine.Stage.EXPIRE);e.receive(nonce,WakeCheckEngine.Stage.EXPIRE);new WakeCheckEngine(s,p,c).reconcile();assertEquals(1,p.rings);assertEquals(WakeCheckState.Phase.EXPIRED,s.state.phase);}
 @Test public void supersededOccurrenceRevokesPromptExpiryAndConfirm(){prompt();p.owner=false;c.advance(120000);e.receive(nonce,WakeCheckEngine.Stage.EXPIRE);assertEquals(WakeCheckState.Phase.CANCELLED,s.state.phase);p.owner=true;assertFalse(e.confirm(nonce));assertEquals(0,p.rings);}
 @Test public void unrelatedAlarmEditsCannotCancelThisCheckButTurningItsCheckOffDoes(){prompt();e.edited(2,false);e.edited(1,true);assertEquals(WakeCheckState.Phase.PROMPT,s.state.phase);e.edited(1,false);assertEquals(WakeCheckState.Phase.CANCELLED,s.state.phase);assertFalse(e.confirm(nonce));}
 @Test public void newDismissalReplacesSinglePendingCheckWithoutOldRepliesAffectingIt(){prompt();String next=UUID.randomUUID().toString();e.arm(WakeCheckState.waiting(next,"next","{}","Weekend",2,60000,false,c));e.receive(nonce,WakeCheckEngine.Stage.EXPIRE);assertFalse(e.confirm(nonce));assertEquals(next,s.state.nonce);assertEquals(WakeCheckState.Phase.WAITING,s.state.phase);assertEquals(0,p.rings);}
 @Test public void wallClockChangesCannotShortenOrExtendSameBootWindow(){prompt();c.wall+=86400000;assertEquals(120000,s.state.remaining(c));c.wall-=172800000;e.reconcile();assertEquals(120000,p.delay);c.elapsed+=120000;e.receive(nonce,WakeCheckEngine.Stage.EXPIRE);assertEquals(1,p.rings);}
 @Test public void rebootUsesSavedWallDeadlineWithoutResettingWindow(){prompt();c.advance(30000);c.boot++;c.elapsed=1000;e.reconcile();assertEquals(90000,p.delay);assertEquals(90000,s.state.remaining(c));c.advance(90000);e.receive(nonce,WakeCheckEngine.Stage.EXPIRE);assertEquals(1,p.rings);}
 @Test public void missingPrerequisitesDoNotCreateUnseenAutomaticRering(){p.access="Allow notifications";e.arm(waiting());assertEquals(0,p.scheduled);assertFalse(s.state.error.isEmpty());c.advance(1000000);e.receive(nonce,WakeCheckEngine.Stage.PROMPT);assertEquals(0,p.shown);assertEquals(0,p.rings);p.access="";e.retry(nonce);assertEquals(120000,s.state.remaining(c));assertEquals(1,p.shown);}
 @Test public void failedDeliveryRetryPreservesNonceAndDeadlineAndCannotExtendExpiredWindow(){e.arm(waiting());p.failShow=true;c.advance(600000);e.receive(nonce,WakeCheckEngine.Stage.PROMPT);long deadline=s.state.deadlineElapsed;assertFalse(s.state.delivered);assertFalse(s.state.error.isEmpty());c.advance(30000);e.retry(nonce);assertEquals(deadline,s.state.deadlineElapsed);assertEquals(nonce,s.state.nonce);c.advance(90000);p.failShow=false;e.retry(nonce);assertEquals(WakeCheckState.Phase.CANCELLED,s.state.phase);assertEquals(0,p.shown);assertEquals(0,p.rings);}
 @Test public void expirySchedulingFailureCanRetryWithoutRepostingOrExtending(){e.arm(waiting());c.advance(600000);p.failSchedule=true;e.receive(nonce,WakeCheckEngine.Stage.PROMPT);long deadline=s.state.deadlineElapsed;assertTrue(s.state.delivered);assertFalse(s.state.error.isEmpty());c.advance(40000);p.failSchedule=false;e.retry(nonce);assertEquals(80000,p.delay);assertEquals(deadline,s.state.deadlineElapsed);assertEquals(1,p.shown);}
 @Test public void storageFailureBeforeClaimPreventsEffectAndUncertainRingFailureIsNotRepeated(){prompt();c.advance(120000);s.fail=true;assertThrows(IllegalStateException.class,()->e.receive(nonce,WakeCheckEngine.Stage.EXPIRE));assertEquals(0,p.rings);s.fail=false;p.failRing=true;e.receive(nonce,WakeCheckEngine.Stage.EXPIRE);assertEquals(1,p.rings);assertEquals(WakeCheckState.Phase.CLAIMED,s.state.phase);e.retry(nonce);e.receive(nonce,WakeCheckEngine.Stage.EXPIRE);assertEquals(1,p.rings);assertFalse(s.state.error.isEmpty());}
 @Test public void interruptedPromptDeliveryRecoversWithOriginalWindow(){e.arm(waiting());c.advance(600000);s.save(s.state.prompt(c));c.advance(30000);new WakeCheckEngine(s,p,c).reconcile();assertEquals(1,p.shown);assertEquals(90000,p.delay);assertEquals(90000,s.state.remaining(c));}
 @Test public void legacyMigrationRejectsDifferentOrCurrentlyRingingAlarmInsteadOfInventingOwnership(){assertTrue(WakeCheckState.legacyEligible(1,1,1,false));assertFalse(WakeCheckState.legacyEligible(1,1,2,false));assertFalse(WakeCheckState.legacyEligible(1,2,1,false));assertFalse(WakeCheckState.legacyEligible(0,0,0,false));assertFalse(WakeCheckState.legacyEligible(1,1,1,true));}
 @Test public void legacyDeliveryCreatesNewWindowOnlyWhenActuallyDelivered(){WakeCheckState legacy=WakeCheckState.waiting(nonce,"","{}","Legacy",1,0,true,c);e.arm(legacy);assertEquals(0,p.shown);e.receive(nonce,WakeCheckEngine.Stage.PROMPT);assertEquals(120000,s.state.remaining(c));assertEquals(1,p.shown);assertEquals(0,p.rings);}
}
